# Mock F Paper 1 wrong-answer data. 'F: ' formula first, 'C: ' calculation step per line.
W={}
def w(n,sel,trig,rule,expl): W[n]=dict(sel=sel,trig=trig,rule=rule,expl=expl)
w(3,["Hansen then reviews the investment in the Crescent","Hansen observes that Crescent's returns","@Exhibit 2"],["always takes a long position in the natural gas futures contract with the shortest maturity","rolls forward the existing contract to the new contract with the shortest maturity","26 June | 1.795 | 1.795 | 2.338 | 2.546"],
 "Roll return compares the NEAR-term contract with the FAR-term contract you roll into, not with the spot price. Near > far (backwardation) → positive for a long. Near < far (contango) → negative.",
 ["F: Roll return = (Near-term futures price − Farther-term futures price) / Near-term futures price",
  "On 26 June the June contract is the near-term contract (1.795) and July is the next one (2.338).",
  "C: Roll return = (1.795 − 2.338) / 1.795",
  "C: = −0.543 / 1.795 = −30.3%",
  "Negative → the curve is in contango and a long position loses on the roll (A).",
  "Your pick B (zero) would need June = July. June equals the SPOT price (1.795), but the roll is from June into July (2.338).",
  "Option C only appears if the numerator is reversed (far − near)."])
